Write pytest tests for clean_users that drops rows with missing names, checking shape and remaining index values.

import pandas as pd

def clean_users(df):
    return df.dropna(subset=['name'])

output:
import pandas as pd
import pytest
from cleaning import clean_users

@pytest.fixture
def users_df():
    return pd.DataFrame({'name': ['Ann', None, 'Bob'], 'age': [31, 25, None]})

def test_clean_users_shape(users_df):
    cleaned = clean_users(users_df)
    assert cleaned.shape == (2, 2)

def test_clean_users_index(users_df):
    cleaned = clean_users(users_df)
    assert list(cleaned.index) == [0, 2]

import pandas as pd
from filtering import filter_active

def make_df():
    return pd.DataFrame({'id': [1, 2, 3], 'active': [True, False, True]})

def test_filter_active():
    result = filter_active(make_df())
    expected = pd.DataFrame({'id': [1, 3], 'active': [True, True]}, index=[0, 2])
    pd.testing.assert_frame_equal(result, expected)

def test_filter_active_empty():
    df = pd.DataFrame({'id': [1], 'active': [False]})
    assert filter_active(df).empty

