Write pytest tests for sales_by_region that groups by region and sums amounts, asserting the resulting series name and values.

import pandas as pd

def sales_by_region(df):
    return df.groupby('region')['amount'].sum()

output:
import pandas as pd
import pytest
from reports import sales_by_region

@pytest.fixture
def sales_df():
    return pd.DataFrame({
        'region': ['east', 'west', 'east'],
        'amount': [100.0, 250.5, 50.5],
    })

def test_sales_by_region(sales_df):
    result = sales_by_region(sales_df)
    assert result['east'] == 150.5
    assert result['west'] == 250.5

def test_sales_by_region_name(sales_df):
    assert sales_by_region(sales_df).name == 'amount'

