Write pytest tests for build_pivot that creates a pivot table of sales by region and product, checking a specific cell value.

import pandas as pd

def build_pivot(df):
    return df.pivot_table(index='region', columns='product', values='amount', aggfunc='sum', fill_value=0)

output:
import pandas as pd
import pytest
from pivots import build_pivot

@pytest.fixture
def sales():
    return pd.DataFrame({
        'region': ['east', 'east', 'west'],
        'product': ['a', 'b', 'a'],
        'amount': [10, 20, 30],
    })

def test_build_pivot_cell(sales):
    table = build_pivot(sales)
    assert table.loc['east', 'a'] == 10
    assert table.loc['east', 'b'] == 20
    assert table.loc['west', 'a'] == 30

def test_build_pivot_no_nans(sales):
    table = build_pivot(sales)
    assert not table.isna().any().any()

