import pandas as pd
from filtering import query_active_high_value

def test_query_filters_both_conditions():
    df = pd.DataFrame({
        'active': [True, True, False],
        'amount': [200, 50, 300],
        'label': ['keep1', 'too-small', 'inactive'],
    })
    result = query_active_high_value(df)
    assert list(result['label']) == ['keep1']

